mapper.select:
select cc.*, (select group_concat(DATE_FORMAT(fcp.mdate, '%Y-%m-%d') order by fcp.branch separator ',') from FIN_CASH_info fci inner join FIN_CASH_PLAN fcp on fci.cash_id = fcp.cash_id and fci.finprod_id = fcp.finprod_id and fci.branch = fcp.branch where fci.finprod_id = cc.finprodId and fci.cash_type_2 = 'C19' and instr(cc.branchAll,fcp.branch)>0) fxmdateStr from ( select sum(dd.theoryAmount) theoryAmt, sum(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt, group_concat(dd.cashType order by dd.branch separator ',') cashType, group_concat(dd.branchType order by dd.branch separator ',') branchType, group_concat(dd.branch order by dd.branch separator ',') branchAll, group_concat(dd.isAccrPenaltyInt1 order by dd.branch separator ',') isAccrPenaltyInt, group_concat(dd.penaltyBaseType1 order by dd.branch separator ',') penaltyBaseType, group_concat(dd.fxYield1 order by dd.branch separator ',') fxYield, group_concat(dd.isRushBack1 order by dd.branch separator ',') isRushBack, dd.finprodId, dd.finprodMarketId, dd.finprodName, min(dd.vdate) vdate, dd.mdate, dd.endPayDate, dd.finprodType2, dd.finprodTypeName, DATE_FORMAT(min(dd.vdate), '%Y-%m-%d') vdateStr, DATE_FORMAT(dd.mdate, '%Y-%m-%d') mdateStr, dd.secAcctId, dd.secAcctName secManageAcctName, dd.chIldName from ( select fcp.CASH_TYPE cashType, fp.FINPROD_ID finprodId, fp.finprod_market_id finprodMarketId, fpty.TYPE_8 finprodType2, (select item_value from sys_datadict_list where item_code=fpty.TYPE_8 and dict_code='PINAN_ASSET_TYPE' ) finprodTypeName, IFNULL(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, ftp.VDATE vdate, ftp.MDATE mdate, IFNULL(bb.amount,0) theoryAmount, IFNULL(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE =#{BRANCH_TYPE_D01} then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE =#{BRANCH_TYPE_D02} then aa.amount else 0 end theoryInterest, (select max(SETTLE_DATE) from TRD_FIN_PRODUCT_DEAL_TOTAL where FINPROD_ID = ftp.FINPROD_ID and MDATE = ftp.MDATE AND p_trade_id is null and is_cancel='N' and IS_OVERDUE_DEAL ='Y' and ( (CASE WHEN SEC_MANAGE_ACCT_ID=NULL THEN '999999' ELSE SEC_MANAGE_ACCT_ID END)
=aa.secAcctId or (CASE WHEN CHL_ID=NULL THEN '999999' ELSE CHL_ID END)
=aa.secAcctId) and PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})) endPayDate, IFNULL(receival.intTotAmt,0) * IFNULL(bb.amount,0) / (select sum(rece_amt + ( select IFNULL(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.branch = ftp.branch and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) penalty, (select sum(tdta.PENALTY_INTAMT) from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID WHERE tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54}) and tdta.MP_FINPROD_ID is null and tfpdt.p_totle_trade_id is null AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.is_overdue_deal='Y' and (tfpdt.is_clean='N' OR tfpdt.is_clean IS NULL) AND tfpdt.FINPROD_ID = aa.finprodId and tfpdt.branch = aa.branch and (tfpdt.SEC_MANAGE_ACCT_ID = (CASE WHEN aa.secAcctId =null THEN '999999' ELSE aa.secAcctId END)
or tfpdt.CHL_ID = (CASE WHEN aa.secAcctId=null THEN '999999' ELSE aa.secAcctId END)
) ) realityPenalty, ftpa.IS_ACCR_PENALTY_INT isAccrPenaltyInt1, ftpa.PENALTY_BASE_TYPE penaltyBaseType1, ftp.IS_RUSH_BACK isRushBack1, fccr.YIELD * 100 fxYield1, ftp.BRANCH branch, ftp.BRANCH_TYPE branchType, aa.secAcctId secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id= aa.secAcctId) secAcctName, (SELECT IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = aa.secAcctId) chIldName from ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE =#{position_type_03} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ) aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join FIN_TRADE_PRODUCT_ADD ftpa ON ftpa.FINPROD_ID = ftp.FINPROD_ID and ftpa.BRANCH = aa.branch left join FIN_CASH_INFO fci on fci.FINPROD_ID = ftp.FINPROD_ID and fci.CASH_TYPE_2= (CASE WHEN ftp.BRANCH_TYPE = #{BRANCH_TYPE_D01} THEN #{CASH_TYPE_2_C01} WHEN #{BRANCH_TYPE_D02} THEN #{CASH_TYPE_2_C02} END) and fci.BRANCH=0 left join FIN_CASH_PLAN fcp on fcp.CASH_ID = fci.CASH_ID and ftp.MDATE = fcp.MDATE left join ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE =#{position_type_03} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ) bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate = case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId INNER join FIN_PRODUCT fp on fp.FINPROD_ID = aa.finprodId left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = aa.finprodId and fpty.BRANCH = 0 left join FIN_CASH_CALC_RULE fccr on fccr.FINPROD_ID = ftp.FINPROD_ID and fccr.BRANCH = ftp.BRANCH and fccr.IS_INITIAL = 'Y' left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch) branch from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId where cdate = #{sysDate} - 1 and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch)) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
AND fpty.TYPE_8 IN(
#{item}
)
and ftp.FINPROD_ID like CONCAT('%', CONCAT(#{finprodMarketId}, '%'))
AND fcp.CASH_TYPE IN(
#{item}
)
AND ftp.MDATE >= STR_TO_DATE(#{registDateStart}, '%Y-%m-%d')
AND ftp.MDATE <= STR_TO_DATE(#{registDateEnd}, '%Y-%m-%d')
) dd group by dd.finprodId, dd.finprodMarketId, dd.finprodName, dd.mdate, dd.endPayDate, dd.finprodType2, dd.finprodTypeName ,dd.secAcctId ,dd.secAcctName ,dd.chIldName order by dd.finprodType2,dd.finprodId,dd.mdate ) cc
left join TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt on tfpdt.finprod_id = cc.finprodId and tfpdt.branch != 0 and instr(cc.branchAll,tfpdt.branch)>0 and (cc.secAcctId=(CASE WHEN tfpdt.sec_manage_acct_id=null THEN '999999' ELSE tfpdt.sec_manage_acct_id END) or cc.secAcctId=(CASE WHEN tfpdt.chl_id=null THEN '999999' ELSE tfpdt.chl_id END) ) AND tfpdt.Is_Cancel='N' AND tfpdt.p_trade_id is null and tfpdt.Is_Clean='Y' and tfpdt.p_totle_trade_id is null WHERE tfpdt.totle_trade_id is null

select fcp.CASH_TYPE cashType, fpty.TYPE_8 finprodType2, (select item_value from sys_datadict_list where item_code=fpty.TYPE_8 and dict_code='PINAN_ASSET_TYPE' ) finprodTypeName, fp.FINPROD_ID finprodId, fp.finprod_market_id finprodMarketId, IFNULL(fp.FINPROD_ABBR,fp.FINPROD_NAME) finprodName, (select min(vdate) from FIN_TRADE_PRODUCT where FINPROD_ID = ftp.FINPROD_ID and branch in (ftp.branch,ftp2.branch)) vdate, DATE_FORMAT((select min(vdate) from FIN_TRADE_PRODUCT where FINPROD_ID = ftp.FINPROD_ID and branch in (ftp.branch,ftp2.branch)), '%Y-%m-%d') vdateStr, ftp.MDATE mdate, DATE_FORMAT(ftp.MDATE,'%Y-%m-%d') mdateStr, aa.endPayDate endPayDate, IFNULL(bb.amount,0) theoryAmt, IFNULL(aa.realityAmount,0) fpriceAmt, (SELECT IFNULL(SUM(PENALTY_INT_TOT_AMT),0) FROM PTL_SEC_RECEIVABLES psr INNER JOIN PTL_PORTFOLIO pp ON psr.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN VW_REPAY_WITHOUT_INT pni ON pni.BRANCH = psr.branch AND psr.FINPROD_ID = pni.finprodId WHERE psr.FINPROD_ID = ftp.finprod_id AND psr.branch = ftp.branch AND IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' AND psr.CDATE = aa.endPayDate-1 ) * IFNULL(bb.amount,0)/ (select sum(rece_amt + ( select IFNULL(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.branch = ftp.branch and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) theoryPenaltyInt, IFNULL(aa.realityPenalty,0) penaltyIntamt, ftp.IS_RUSH_BACK isRushBack, (CASE WHEN ftp.BRANCH_TYPE='D01' THEN ftp.BRANCH ELSE ftp2.BRANCH) bjBranch,
(CASE WHEN ftp.BRANCH_TYPE='D02' THEN ftp.BRANCH ELSE ftp2.BRANCH) liBranch, ftp.BRANCH_TYPE, IFNULL(aa.secAcctId,aa.chlId) secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id= aa.secAcctId) secManageAcctName, (SELECT IFNULL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = aa.chlId) chIldName from (select sum(tfpdt.FPRICE_AMT) realityAmount, sum(tdta.PENALTY_INTAMT) realityPenalty, tfpdt.BRANCH branch, tfpdt.FINPROD_ID finprodId, tfpdt.mDate mdate, tfpdt.SEC_MANAGE_ACCT_ID secAcctId, tfpdt.CHL_ID chlId, max(SETTLE_DATE) endPayDate from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = tfpdt.FINPROD_ID and fpty.BRANCH = 0 where tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54}) and tdta.MP_FINPROD_ID is null and tfpdt.p_totle_trade_id is null and fpty.TYPE_8 in (#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06}) AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.is_overdue_deal='Y' and tfpdt.is_clean='Y' and tfpdt.portfolio_id is null GROUP BY tfpdt.FINPROD_ID,tfpdt.BRANCH,tfpdt.MDATE,tfpdt.SEC_MANAGE_ACCT_ID,tfpdt.CHL_ID ) aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join FIN_CASH_INFO fci on fci.FINPROD_ID = ftp.FINPROD_ID and fci.CASH_TYPE_2 = (CASE WHEN ftp.BRANCH_TYPE=#{BRANCH_TYPE_D01} THEN #{CASH_TYPE_2_C01} WHEN #{BRANCH_TYPE_D02} THEN #{CASH_TYPE_2_C02} END ) and fci.BRANCH=0 left join FIN_CASH_PLAN fcp on fcp.CASH_ID = fci.CASH_ID and ftp.MDATE = fcp.MDATE left join FIN_PRODUCT fp on fp.FINPROD_ID = aa.finprodId left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = aa.finprodId and fpty.BRANCH = 0 left join ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = #{rec_type_02} and lixi.REC_TYPE =#{rec_type_03})) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.PAY_DATE payDate, prp.CDATE cdate from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE =#{position_type_03} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in (#{rec_type_01}, #{rec_type_02}) and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID ) bb on ftp.FINPROD_ID = bb.finprodId and bb.payDate = fcp.PAY_DATE and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and (bb.secAcctId = (CASE WHEN aa.secAcctId=null THEN '999999' ELSE aa.secAcctId END) or bb.secAcctId = (CASE WHEN aa.chlId=null THEN '999999' ELSE aa.chlId END)) left join FIN_TRADE_PRODUCT ftp2 on ftp.FINPROD_ID = ftp2.FINPROD_ID and ftp.BRANCH != ftp2.branch and ftp.mdate = ftp2.mdate
exists ( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID where tdta.MP_FINPROD_ID is null and tfpdt.p_totle_trade_id is null AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.IS_OVERDUE_DEAL= 'Y' AND tfpdt.IS_CLEAN = 'Y' AND tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54}) AND aa.finprodId = tfpdt.FINPROD_ID and aa.mdate = tfpdt.mdate and (tfpdt.SEC_MANAGE_ACCT_ID = aa.secAcctId or tfpdt.CHL_ID = aa.chlId or tfpdt.SEC_MANAGE_ACCT_ID is null or tfpdt.CHL_ID is null) and tfpdt.portfolio_id is null )
AND fp.FINPROD_TYPE2 IN(
#{item}
)
and ftp.FINPROD_ID like CONCAT('%', CONCAT(#{finprodMarketId}, '%'))
AND fcp.CASH_TYPE IN(
#{item}
)
AND ftp.MDATE >= STR_TO_DATE(#{registDateStart}, '%Y-%m-%d')
AND ftp.MDATE <= STR_TO_DATE(#{registDateEnd}, '%Y-%m-%d')
order by fp.FINPROD_TYPE2,ftp.FINPROD_ID,ftp.mdate

select dd.finprodId, (select group_concat(PORTFOLIO_ID order by VDATE separator ',') from PTL_PORTFOLIO where PARENT_PORTFOLIO_ID =dd.portfolioId) childPortfolioIds, dd.portfolioId,dd.portfolioName, SUM(dd.theoryAmount) theoryAmt, SUM(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt from ( select ftp.FINPROD_ID finprodId, aa.portfolioId, (select portfolio_name from ptl_portfolio where portfolio_id = aa.portfolioId) portfolioName, IFNULL(bb.amount,0) theoryAmount, IFNULL(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE ='D01' then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE ='D02' then aa.amount else 0 end theoryInterest, IFNULL(receival.intTotAmt,0) * IFNULL(bb.amount,0) / (select sum(rece_amt + ( select IFNULL(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.PORTFOLIO_ID =aa.portfolioid and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.PORTFOLIO_ID =aa.portfolioid and psr.branch = ftp.branch and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and psr.CDATE = ftp.mdate) penalty, (select sum(tdta.PENALTY_INTAMT) from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt inner join PTL_PORTFOLIO pp on tfpdt.PORTFOLIO_ID = pp.PORTFOLIO_ID left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID WHERE tfpdt.PS in ('T09','T08','T07','T54') and tdta.MP_FINPROD_ID is null AND tfpdt.TRADE_STATUS ='01' AND tfpdt.IS_CANCEL = 'N' and tfpdt.is_overdue_deal='Y' and (tfpdt.is_clean='N' OR tfpdt.is_clean IS NULL) AND tfpdt.FINPROD_ID = aa.finprodId and tfpdt.branch = aa.branch and tfpdt.PORTFOLIO_ID = aa.portfolioId and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and (tfpdt.SEC_MANAGE_ACCT_ID = (CASE WHEN aa.secAcctId = null THEN '999999' ELSE aa.secAcctId END) or tfpdt.CHL_ID = (CASE WHEN aa.secAcctId = null THEN '999999' ELSE aa.secAcctId END)) ) realityPenalty from ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE = '03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE = '03' and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ) aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE ='03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE =#{position_type_03} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' and prp.REC_TYPE in ('01', '02') and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ) bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId and bb.portfolioId = aa.portfolioId left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch) branch, psr.PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId where cdate = #{sysDate} - 1 and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' group by psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch),psr.PORTFOLIO_ID) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch and receival.PORTFOLIO_ID = aa.portfolioId
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
and aa.finprodId = #{finprodId}
AND aa.branch IN
${item}
and aa.secAcctId = #{secAcctId}
) dd group by dd.finprodId,dd.portfolioId,dd.portfolioName

select dd.finprodId, dd.portfolioId, dd.portfolioName, SUM(dd.theoryAmount) theoryAmt, SUM(dd.realityAmount) fpriceAmt, sum(dd.theoryCapital) theoryPrin, sum(dd.theoryInterest) theoryInt, sum(dd.penalty) theoryPenaltyInt, sum(dd.realityPenalty) penaltyIntamt from ( select ftp.FINPROD_ID finprodId, aa.portfolioId, (select portfolio_name from ptl_portfolio where portfolio_id = aa.portfolioId) portfolioName, IFNULL(bb.amount,0) theoryAmount, IFNULL(bb.amount -aa.amount,0) realityAmount, case when ftp.BRANCH_TYPE ='D01' then aa.amount else 0 end theoryCapital, case when ftp.BRANCH_TYPE ='D02' then aa.amount else 0 end theoryInterest, IFNULL(receival.intTotAmt,0) * IFNULL(bb.amount,0) / (select sum(rece_amt + ( select IFNULL(sum(rece_amt), 0) from PTL_SEC_RECEIVABLES psrr inner join PTL_PORTFOLIO pp on psrr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psrr.branch in (select without_branch from VW_REPAY_WITHOUT_INT where branch = psr.branch and FINPRODID = psr.finprod_id) and psrr.PORTFOLIO_ID =aa.portfolioid and psrr.portfolio_id = psr.portfolio_id and psrr.finprod_id = psr.FINPROD_ID
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and psrr.CDATE = ftp.mdate)) from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID where psr.FINPROD_ID = ftp.finprod_id and psr.PORTFOLIO_ID =aa.portfolioid and psr.branch = ftp.branch
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and psr.CDATE = ftp.mdate) penalty, sffx.sffxje realityPenalty from ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE = '03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE = '03'
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ) aa inner join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = aa.finprodId and ftp.BRANCH = aa.branch left join ( select sum(prp.AMOUNT + (select IFNULL(sum(lixi.amount), 0) from PTL_RECE_POSITION lixi where prp.PAY_DATE = lixi.PAY_DATE and prp.cdate = lixi.cdate and prp.PORTFOLIO_ID = lixi.PORTFOLIO_ID and prp.SEC_ACCT_ID = lixi.SEC_ACCT_ID and prp.FINPROD_ID = lixi.FINPROD_ID and prp.INV_AIM = lixi.INV_AIM and prp.REC_TYPE = '02' and lixi.REC_TYPE ='03')) amount, prp.FINPROD_ID finprodId, prp.SEC_ACCT_ID secAcctId, prp.BRANCH branch, prp.PAY_DATE payDate, prp.CDATE cdate, prp.PORTFOLIO_ID portfolioId from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID where prp.HODING_TYPE =#{position_type_03}
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
and prp.REC_TYPE in ('01', '02') and prp.INPUT_TYPE = '04' group by prp.FINPROD_ID, prp.BRANCH, prp.CDATE, prp.PAY_DATE, prp.SEC_ACCT_ID, prp.PORTFOLIO_ID ) bb on ftp.FINPROD_ID = bb.finprodId and ftp.BRANCH = bb.branch and bb.cdate= case when bb.payDate>ftp.mdate then bb.payDate+1 else ftp.mdate+1 end and bb.secAcctId = aa.secAcctId and bb.portfolioId = aa.portfolioId left join (select sum(psr.PENALTY_INT_AMT) intAmt, sum(psr.PENALTY_INT_TOT_AMT) intTotAmt, psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch) branch, psr.PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr inner join PTL_PORTFOLIO pp on psr.PORTFOLIO_ID = pp.PORTFOLIO_ID inner join FIN_TRADE_PRODUCT ftp on ftp.finprod_id = psr.finprod_id and ftp.branch = psr.branch left join VW_REPAY_WITHOUT_INT pni on psr.branch = pni.WITHOUT_BRANCH and psr.FINPROD_ID = pni.finprodId where cdate = #{sysDate} - 1
and pp.PARENT_PORTFOLIO_ID = #{portfolioId}
group by psr.FINPROD_ID, IFNULL(pni.BRANCH,psr.branch),psr.PORTFOLIO_ID) receival on receival.FINPROD_ID = aa.finprodId and receival.branch =aa.branch and receival.PORTFOLIO_ID = aa.portfolioId left join (select TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, TRD_PRODUCT_DEAL.FINPROD_ID, TRD_PRODUCT_DEAL.CHL_ID, TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, TRD_PRODUCT_DEAL.BRANCH, sum((CASE WHEN TRD_PRODUCT_DEAL.PS = #{PS_T01} THEN TRD_PRODUCT_DEAL.TRADE_AMT*(-1) ELSE TRD_PRODUCT_DEAL.TRADE_AMT END )) sffxje from TRD_PRODUCT_DEAL left join TRD_PRODUCT_DEAL_ADD on TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID where TRD_PRODUCT_DEAL.BUSI_TYPE= #{BUSI_TYPE_37} and TRD_PRODUCT_DEAL.TRADE_STATUS= #{TRADE_STATUS_01} and TRD_PRODUCT_DEAL.IS_CANCEL= #{YES_OR_NO_N} and TRD_PRODUCT_DEAL.TRADE_DATE= #{sysDate} group by TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, TRD_PRODUCT_DEAL.FINPROD_ID, TRD_PRODUCT_DEAL.CHL_ID, TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, TRD_PRODUCT_DEAL.BRANCH ) sffx on aa.finprodId = sffx.FINPROD_ID and aa.BRANCH = sffx.BRANCH and aa.portfolioId = sffx.PORTFOLIO_ID and (IFNULL(IFNULL(sffx.CHL_ID,sffx.SEC_MANAGE_ACCT_ID),'999999')=aa.secAcctId)
aa.cdate = #{sysDate} and aa.payDate < #{sysDate}
and aa.finprodId = #{finprodId}
AND aa.branch IN
${item}
and aa.secAcctId = #{secAcctId}
) dd group by dd.finprodId,dd.portfolioId,dd.portfolioName

select dd.*
,((select IFNULL(sum(aa.amount),0) from (select sum(IFNULL(prp.amount,0)) amount from PTL_RECE_POSITION prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join VW_REPAY_WITHOUT_INT pni on pni.WITHOUT_BRANCH = prp.branch and prp.FINPROD_ID = pni.finprodId
prp.FINPROD_ID = #{finprodId}
AND (prp.branch IN
${item}
or prp.branch in (pni.WITHOUT_BRANCH))
and (prp.SEC_ACCT_ID = #{secAcctId})
and prp.HODING_TYPE='03' and prp.CDATE = #{sysDate} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' group by prp.PORTFOLIO_ID) aa
)+( select IFNULL(sum(aa.amount),0) from ( select sum(IFNULL(prp.amount,0)) amount from PTL_RECE_POSITION_FLOW prp inner join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join VW_REPAY_WITHOUT_INT pni on pni.WITHOUT_BRANCH = prp.branch and prp.FINPROD_ID = pni.finprodId
prp.FINPROD_ID = #{finprodId}
AND (prp.branch IN
${item}
or prp.branch in (pni.WITHOUT_BRANCH))
and (prp.SEC_ACCT_ID = #{secAcctId})
and prp.HODING_TYPE='01' and prp.CDATE = #{sysDate} and IFNULL(pp.PARENT_PORTFOLIO_ID, 'null') = 'null' group by prp.PORTFOLIO_ID ) aa
)
+#{theoryPenaltyInt}
) residueAmount
from ( select tfpdt.TOTLE_TRADE_ID totleTradeId, '有效' tradeStatus, tfpdt.SETTLE_DATE settleDate, tfpdt.TRADE_DATE tradeDate, tfpdt.FPRICE_AMT accountingAmt from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID
and tfpdt.MDATE =STR_TO_DATE(#{mdate},'%Y-%m-%d')
and tfpdt.FINPROD_ID = #{finprodId}
and tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})
and (tfpdt.SEC_MANAGE_ACCT_ID = #{secAcctId} or tfpdt.CHL_ID = #{secAcctId})
AND tfpdt.IS_CANCEL = 'N' and tfpdt.TRADE_STATUS ='01' and tdta.MP_FINPROD_ID is null and tfpdt.P_TOTLE_TRADE_ID is null
union all select tfpdt.TOTLE_TRADE_ID totleTradeId, '流程中' tradeStatus, tfpdt.SETTLE_DATE settleDate, tfpdt.TRADE_DATE tradeDate, tfpdt.FPRICE_AMT accountingAmt from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join WFL_TRD_DEAL_TOTAL_ADD tdta on tfpdt.TOTLE_TRADE_ID = tdta.TOTLE_TRADE_ID
and tfpdt.MDATE =STR_TO_DATE(#{mdate},'%Y-%m-%d')
and tfpdt.FINPROD_ID = #{finprodId}
and tfpdt.PS in (#{PS_T09},#{PS_T08},#{PS_T07},#{PS_T54})
and (tfpdt.SEC_MANAGE_ACCT_ID = #{secAcctId} or tfpdt.CHL_ID = #{secAcctId})
AND tfpdt.IS_CANCEL = 'N' and tfpdt.TRADE_STATUS ='01' and tdta.MP_FINPROD_ID is null and tfpdt.P_TOTLE_TRADE_ID is null
) dd order by dd.tradeDate desc

select (select distinct basis from FIN_CASH_CALC_RULE where finprod_id=ftp.finprod_id and branch=0 and EFF_DATE= (select min(vdate) from fin_trade_product WHERE finprod_id =ftp.finprod_id) and basis is not null ) basis, group_concat(fcp.cash_id order by ftp.branch separator ',') cashIds, (select item_value from sys_datadict_list where item_code = fpty.TYPE_8 and dict_code = 'PINAN_ASSET_TYPE') finprodTypeName, fpty.TYPE_8 finprodType, ftp.FINPROD_TYPE finprodTypeGz, ftp.FINPROD_TYPE2 finprodTypeTg, ftp.finprod_id finprodId, (select DATE_FORMAT(min(vdate), '%Y-%m-%d') from fin_trade_product
and finprod_id = #{finprodId}
and branch in
${item}
) vdateStr, DATE_FORMAT(ftp.mdate,'%Y-%m-%d') mdateStr, DATE_FORMAT(ftp.mdate,'%Y-%m-%d') fxvdateStr, DATE_FORMAT(fcp.mdate,'%Y-%m-%d') fxmdateStr, IFNULL(fp.FINPROD_ABBR, fp.FINPROD_NAME) finprodName, fccr.yield * 100 fxYield, ftp.IS_RUSH_BACK isRushBack, ftpa.is_accr_penalty_int isAccrPenaltyInt, ftpa.penalty_base_type penaltyBaseType from fin_trade_product ftp INNER join FIN_PRODUCT fp on fp.FINPROD_ID = ftp.finprod_id left join FIN_PRODUCT_TYPE fpty on fpty.FINPROD_ID = ftp.finprod_id and fpty.BRANCH = 0 left join fin_trade_product_add ftpa on ftp.finprod_id = ftpa.finprod_id and ftp.branch = ftpa.branch left join FIN_CASH_CALC_RULE fccr on fccr.finprod_id = ftp.finprod_id and fccr.branch = ftp.branch left join Fin_Cash_Plan fcp on fcp.finprod_id = ftp.finprod_id and fcp.branch = ftp.branch
and ftp.finprod_id = #{finprodId}
and ftp.branch in (${bjBranch},${liBranch})
and ftp.branch=${bjBranch}
and ftp.branch=${liBranch}
group by fcp.mdate, fccr.yield, ftp.IS_RUSH_BACK, ftpa.is_accr_penalty_int, ftpa.penalty_base_type, fpty.TYPE_8, ftp.finprod_id, ftp.mdate, IFNULL(fp.FINPROD_ABBR,fp.FINPROD_NAME), ftp.FINPROD_TYPE, ftp.FINPROD_TYPE2

select #{finprodType2} finprodType2, sys_datadict_list.item_value finprodTypeName, FIN_PRODUCT.FINPROD_ID finprodId , FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.TRADE_MARKET tradeMarket, IFNULL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finprodName, FIN_CASH_PLAN.CASH_TYPE cashType, FIN_TRADE_PRODUCT.VDATE vdate, FIN_TRADE_PRODUCT.MDATE mdate, FIN_TRADE_PRODUCT.CCY ccy, IFNULL(FIN_PRODUCT_2.FINPROD_NAME,STL_SEC_ACCT_INFO.SEC_ACCT_NAME) chIldName, #{secManageAcctId} secAcctId,
#{bjBranch} bjBranch,
#{liBranch} liBranch,
CASE WHEN FIN_PRODUCT_2.FINPROD_ID IS NOT NULL THEN 1 ELSE 0 END channel, FIN_PRODUCT_ADD.COLLECT_TYPE collectType from FIN_TRADE_PRODUCT left join FIN_CASH_INFO on FIN_TRADE_PRODUCT.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_2 =
#{CASH_TYPE_2_C01}
#{CASH_TYPE_2_C02}
left join FIN_CASH_PLAN on FIN_CASH_INFO.CASH_ID = FIN_CASH_PLAN.CASH_ID and FIN_TRADE_PRODUCT.MDATE=FIN_CASH_PLAN.MDATE left join FIN_PRODUCT on FIN_TRADE_PRODUCT.FINPROD_ID= FIN_PRODUCT.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO ON STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{secManageAcctId} LEFT JOIN FIN_PRODUCT FIN_PRODUCT_2 ON FIN_PRODUCT_2.FINPROD_ID = #{secManageAcctId} LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD ON FIN_PRODUCT_2.FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN sys_datadict_list on sys_datadict_list.item_code =#{finprodType2} and sys_datadict_list.dict_code=#{PINAN_ASSET_TYPE} where FIN_TRADE_PRODUCT.FINPROD_ID=#{finprodId} and FIN_TRADE_PRODUCT.BRANCH =
#{liBranch}
#{bjBranch}

select
pp.PORTFOLIO_ID id, pp.PORTFOLIO_NAME text,
sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSBJ} THEN IFNULL(prp.AMOUNT,0) ELSE 0 END)) theoryPrin, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSLX} THEN IFNULL(prp.AMOUNT,0) ELSE 0 END)) theoryIntSx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_HBWSLX} THEN IFNULL(prp.AMOUNT,0) ELSE 0 END)) theoryIntHb, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSBJ} THEN IFNULL(fxinfo.RECE_AMT,0) ELSE 0 END)) amountBj, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSLX} THEN IFNULL(fxinfo.RECE_AMT,0) ELSE 0 END)) amountLx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_HBWSLX} THEN IFNULL(fxinfo.RECE_AMT,0) ELSE 0 END)) amountHbWfx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSBJ} THEN IFNULL(fxinfo.PENALTY_INT_AMT,0) ELSE 0 END)) penaltyIntBj, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSLX} THEN IFNULL(fxinfo.PENALTY_INT_AMT,0) ELSE 0 END)) penaltyIntLx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_HBWSLX} THEN IFNULL(fxinfo.PENALTY_INT_AMT,0) ELSE 0 END)) penaltyIntHbWfx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSBJ} THEN IFNULL(actInfo.actPayInt,0) ELSE 0 END)) actPenaltyIntBj, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_YQWSLX} THEN IFNULL(actInfo.actPayInt,0) ELSE 0 END)) actPenaltyIntLx, sum((CASE WHEN prp.REC_TYPE=#{RECE_TYPE_HBWSLX} THEN IFNULL(actInfo.actPayInt,0) ELSE 0 END)) actPenaltyIntHbWfx from PTL_RECE_POSITION prp
left join VW_REPAY_WITHOUT_INT vrwi on prp.BRANCH = vrwi.WITHOUT_BRANCH and prp.FINPROD_ID = vrwi.FINPRODID
left join ( select sum(IFNULL(PENALTY_INT_AMT,0)) PENALTY_INT_AMT, sum(IFNULL(RECE_AMT,0)) RECE_AMT, FINPROD_ID, BRANCH, PORTFOLIO_ID from PTL_SEC_RECEIVABLES psr where CDATE = #{sysDate} -1 group by FINPROD_ID,BRANCH,PORTFOLIO_ID ) fxinfo on fxinfo.FINPROD_ID = prp.FINPROD_ID and prp.BRANCH = fxinfo.BRANCH and fxinfo.PORTFOLIO_ID = prp.PORTFOLIO_ID
left join ( select tfpdt.PORTFOLIO_ID, tfpdt.FINPROD_ID, tfpdt.BRANCH, IFNULL( (CASE WHEN tfpdt.PS = #{PS_YSKZR} THEN tfpdt.TRADE_AMT*-1 ELSE tfpdt.TRADE_AMT END),0) actPayInt, tfpdt.SEC_MANAGE_ACCT_ID, tfpdt.CHL_ID from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL paTotal on paTotal.TOTLE_TRADE_ID = tfpdt.TOTLE_TRADE_ID where tfpdt.BUSI_TYPE = #{BUSI_TYPE_YQJY} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_CS} and IFNULL(tfpdt.IS_CANCEL,#{YN_N}) = #{YN_N} and tfpdt.TRADE_DATE = #{sysDate} ) actInfo on actInfo.FINPROD_ID = prp.FINPROD_ID and prp.BRANCH = actInfo.BRANCH and actInfo.PORTFOLIO_ID = prp.PORTFOLIO_ID and (actInfo.SEC_MANAGE_ACCT_ID = prp.SEC_ACCT_ID or actInfo.CHL_ID = prp.SEC_ACCT_ID) left join PTL_PORTFOLIO pp on prp.PORTFOLIO_ID = pp.PORTFOLIO_ID
pp.INVEST_YESORNO = #{YON_Y}
and (instr(pp.PORTFOLIO_ID, #{search}) > 0 or instr(pp.PORTFOLIO_NAME, #{search}) > 0 )
and pp.PORTFOLIO_ID = #{initValue}
and prp.BRANCH in (
#{bjBranch}
,
#{liBranch}
)
and prp.FINPROD_ID = #{finprodId}
and prp.CDATE = #{sysDate} and prp.SEC_ACCT_ID = #{secAcctId} and prp.HODING_TYPE = #{POSITION_TYPE_SJ}
and pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
group by prp.SEC_ACCT_ID,prp.FINPROD_ID,prp.INV_AIM,prp.PAY_DATE,pp.PORTFOLIO_ID,pp.PORTFOLIO_NAME

select group_concat(fcp.cash_id order by ftp.branch separator  ',')  cashIds from fin_trade_product ftp
  left join Fin_Cash_Plan fcp on fcp.finprod_id = ftp.finprod_id
                             and fcp.branch = ftp.branch

        and  ftp.finprod_id =#{finprodId}

        and ftp.branch in

            ${item}

 select group_concat(WITHOUT_BRANCH order by WITHOUT_BRANCH separator ',')  withoutBranch
 from vw_repay_without_int
where FINPRODID = #{finprodId}
  and BRANCH = ${liBranch}
